export function langOf(_lang?: string): Lang {
  return 'ru';
}

export function t(lang: Lang, key: string, vars: Record<string, string | number> = {}): string {
  const s = (lang === 'ru' ? RU[key] : undefined) ?? key;
  return s.replace(/\{(\w+)\}/g, (m, k: string) => (k in vars ? String(vars[k]) : m));
}

/** Форма слова «слово» для n (Intl.PluralRules языка интерфейса): 1 слово, 2 слова, 5 слов; 1 word, 2 words. */
export function wordsN(lang: Lang, n: number): string {
  const cat = new Intl.PluralRules(lang).select(n);
  return t(lang, `pt.word.${cat}`) === `pt.word.${cat}` ? t(lang, 'pt.word.other') : t(lang, `pt.word.${cat}`);
}
